CREATE TABLE dim_customer (customer_id BIGINT PRIMARY KEY, signup_date DATE, state VARCHAR(80), city VARCHAR(80), customer_segment VARCHAR(40), acquisition_channel VARCHAR(40), age INT, annual_income_inr NUMERIC(14,2), gender VARCHAR(20));
CREATE TABLE dim_product (product_id INT PRIMARY KEY, product_name VARCHAR(150), category VARCHAR(80), subcategory VARCHAR(80), list_price_inr NUMERIC(14,2), gross_margin_rate NUMERIC(6,4), weight_kg NUMERIC(8,2), abc_class CHAR(1));
CREATE TABLE fact_order (order_id BIGINT PRIMARY KEY, customer_id BIGINT REFERENCES dim_customer(customer_id), order_date DATE, order_channel VARCHAR(30), payment_method VARCHAR(30), order_status VARCHAR(20), discount_rate NUMERIC(8,4), shipping_cost_inr NUMERIC(14,2), product_id INT REFERENCES dim_product(product_id), quantity INT, unit_price_inr NUMERIC(14,2), gross_sales_inr NUMERIC(16,2), discount_inr NUMERIC(16,2), net_sales_inr NUMERIC(16,2), gross_profit_inr NUMERIC(16,2), marketing_cost_inr NUMERIC(16,2), contribution_profit_inr NUMERIC(16,2), is_returned INT);
CREATE INDEX idx_order_customer ON fact_order(customer_id); CREATE INDEX idx_order_date ON fact_order(order_date); CREATE INDEX idx_order_product ON fact_order(product_id);
